$ErrorActionPreference = "Stop"

$root = Get-Location
Write-Host "Applying NaijaDrops update: driver-viewed indicator, rider bid profiles, rider realtime fallback poll" -ForegroundColor Cyan

function Write-FileFromBase64 {
    param(
        [string]$RelativePath,
        [string]$Base64Content
    )
    $fullPath = Join-Path $root $RelativePath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    if (Test-Path -LiteralPath $fullPath) {
        $timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
        $backupPath = "$fullPath.bak_$timestamp"
        Copy-Item -LiteralPath $fullPath -Destination $backupPath -Force
        Write-Host "  Backed up existing file to $backupPath" -ForegroundColor DarkGray
    }
    $bytes = [System.Convert]::FromBase64String($Base64Content)
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "  Wrote $RelativePath" -ForegroundColor Green
}

$trackingB64 = ""
Write-FileFromBase64 -RelativePath "src/app/tracking/[orderId]/page.jsx" -Base64Content $trackingB64

$dashboardB64 = ""
Write-FileFromBase64 -RelativePath "src/app/rider/(main)/dashboard/page.jsx" -Base64Content $dashboardB64

$activejobB64 = ""
Write-FileFromBase64 -RelativePath "src/app/rider/(main)/active-job/page.jsx" -Base64Content $activejobB64

Write-Host ""
Write-Host "Done. Changes in this update:" -ForegroundColor Cyan
Write-Host "  1. Vendor tracking page: 'X riders viewed your request' widget + avatar stack while waiting for a rider"
Write-Host "  2. Vendor tracking page: incoming bid cards now show the rider's photo, name, and rating"
Write-Host "  3. Rider dashboard + active-job: 20s fallback poll on top of realtime, so a dropped websocket no longer leaves the screen stuck on the old state until a manual refresh"
Write-Host ""
Write-Host "A Supabase migration (vendor_view_order_broadcasts) was already applied directly to the live project - it adds a SECURITY DEFINER-backed RLS policy so vendors can read order_broadcasts for their own orders (needed for the viewed-count). No action needed for that part." -ForegroundColor Yellow
Write-Host ""
Write-Host "Review the diffs, then:" -ForegroundColor Cyan
Write-Host "  git add -A"
Write-Host "  git commit -m 'Add driver-viewed indicator, rider profiles on bids, realtime fallback poll'"
Write-Host "  git push origin main"
